'use client'

import { useState } from 'react'

export default function Home() {
  const [form, setForm] = useState({
    name: '',
    email: '',
    activity_type: '',
    timestamp: new Date().toISOString(),
  });

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    await fetch('http://localhost:8080/track', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(form),
    });
    alert('Event sent!');
  };

  return (
    <main className="p-6 max-w-md mx-auto">
      <h1 className="text-2xl mb-4">Event Tracker</h1>
      <form onSubmit={handleSubmit} className="flex flex-col gap-4">
        <input name="name" placeholder="Name" value={form.name} onChange={handleChange} />
        <input name="email" placeholder="Email" value={form.email} onChange={handleChange} />
        <input name="activity_type" placeholder="Activity" value={form.activity_type} onChange={handleChange} />
        <button type="submit" className="bg-blue-600 text-white px-4 py-2">Track Event</button>
      </form>
    </main>
  );
}
